macro_rules! deps {
    () => {
        QopSet!();
        Algorithm!();
    };
}

macro_rules! DigestClient {
    () => {
        deps!();
        # [doc = " Client for a `Digest` challenge, as in [RFC 7616](https://datatracker.ietf.org/doc/html/rfc7616)."] # [doc = ""] # [doc = " This can be constructed by the `TryFrom<&ChallengeRef<'_>>` impl. However,"] # [doc = " in most cases this client should be used only indirectly through the more"] # [doc = " abstract [`crate::PasswordClient`]."] # [doc = ""] # [doc = " Most of the information here is taken from the `WWW-Authenticate` or"] # [doc = " `Proxy-Authenticate` header. This also internally maintains a nonce counter."] # [doc = ""] # [doc = " ## Implementation notes"] # [doc = ""] # [doc = " *   Recalculates `H(A1)` on each [`DigestClient::respond`] call. It'd be"] # [doc = "     more CPU-efficient to calculate `H(A1)` only once by supplying the"] # [doc = "     username and password at construction time or by caching (username,"] # [doc = "     password) -> `H(A1)` mappings internally. `DigestClient` prioritizes"] # [doc = "     simplicity instead."] # [doc = " *   There's no support yet for parsing the `Authentication-Info` and"] # [doc = "     `Proxy-Authentication-Info` header fields described by [RFC 7616 section"] # [doc = "     3.5](https://datatracker.ietf.org/doc/html/rfc7616#section-3.5)."] # [doc = "     PRs welcome!"] # [doc = " *   Always responds using `UTF-8`, and thus doesn't use or keep around the `charset`"] # [doc = "     parameter. The RFC only allows that parameter to be set to `UTF-8` anyway."] # [doc = " *   Supports [RFC 2069](https://datatracker.ietf.org/doc/html/rfc2069) compatibility as in"] # [doc = "     [RFC 2617 section 3.2.2.1](https://datatracker.ietf.org/doc/html/rfc2617#section-3.2.2.1),"] # [doc = "     even though RFC 7616 drops it. There are still RTSP cameras being sold"] # [doc = "     in 2021 that use the RFC 2069-style calculations."] # [doc = " *   Supports RFC 7616 `userhash`, even though it seems impractical and only"] # [doc = "     marginally useful. The server must index the userhash for each supported"] # [doc = "     algorithm or calculate it on-the-fly for all users in the database."] # [doc = " *   The `-sess` algorithm variants haven't been tested; there's no example"] # [doc = "     in the RFCs."] # [doc = ""] # [doc = " ## Security considerations"] # [doc = ""] # [doc = " We strongly advise *servers* against implementing `Digest`:"] # [doc = ""] # [doc = " *   It's actively harmful in that it prevents the server from securing their"] # [doc = "     password storage via salted password hashes. See [RFC 7616 Section"] # [doc = "     5.2](https://datatracker.ietf.org/doc/html/rfc7616#section-5.2)."] # [doc = "     When your server offers `Digest` authentication, it is advertising that"] # [doc = "     it stores plaintext passwords!"] # [doc = " *   It's no replacement for TLS in terms of protecting confidentiality of"] # [doc = "     the password, much less confidentiality of any other information."] # [doc = ""] # [doc = " For *clients*, when a server supports both `Digest` and `Basic`, we advise"] # [doc = " using `Digest`. It provides (slightly) more confidentiality of passwords"] # [doc = " over the wire."] # [doc = ""] # [doc = " Some servers *only* support `Digest`. E.g.,"] # [doc = " [ONVIF](https://www.onvif.org/profiles/specifications/) mandates the"] # [doc = " `Digest` scheme. It doesn't prohibit implementing other schemes, but some"] # [doc = " cameras meet the specification's requirement and do no more."] # [derive (Eq , PartialEq)] pub struct DigestClient { # [doc = " Holds unescaped versions of all string fields."] # [doc = ""] # [doc = " Using a single `String` minimizes the size of the `DigestClient`"] # [doc = " itself and/or any option/enum it may be wrapped in. It also minimizes"] # [doc = " padding bytes after each allocation. The fields as stored as follows:"] # [doc = ""] # [doc = " 1.  `realm`: `[0, domain_start)`"] # [doc = " 2.  `domain`: `[domain_start, opaque_start)`"] # [doc = " 3.  `opaque`: `[opaque_start, nonce_start)`"] # [doc = " 4.  `nonce`: `[nonce_start, buf.len())`"] buf : Box < str > , domain_start : u16 , opaque_start : u16 , nonce_start : u16 , algorithm : Algorithm , session : bool , stale : bool , rfc2069_compat : bool , userhash : bool , qop : QopSet , nc : u32 , }
    };
}

DigestClient!()